  terminal = pty.spawn(executable, args, { cwd: work, env, name: 'xterm-256color', cols: 120, rows: 40 });
  terminal.onData(data => { output += stripVTControlCharacters(data); });
  terminal.onExit(() => { exited = true; });
}

